+
+.emoji-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    padding: 4px 6px;
+    border-radius: 4px;
+    cursor: pointer;
+}
+
+.emoji-btn:hover {
+    background: #404249;
+}
+
+/* Message Input */
+.message-input {
+    display: flex;
+    gap: 8px;
+    padding: 12px 20px;
+    border-top: 1px solid #3f4147;
+    flex-shrink: 0;
