+
+.message-input textarea {
+    flex: 1;
+    background: #383a40;
+    border: none;
+    border-radius: 8px;
+    padding: 10px 14px;
+    color: #dbdee1;
+    font-size: 0.9rem;
+    resize: none;
+    font-family: inherit;
+    outline: none;
