+
+.message-input textarea:focus {
+    box-shadow: 0 0 0 2px #5865f2;
+}
+
+.message-input textarea::placeholder {
+    color: #6d6f78;
+}
+
+.btn-send {
+    background: #5865f2;
+    color: #fff;
+    border: none;
+    border-radius: 8px;
+    padding: 10px 18px;
+    font-weight: 600;
+    font-size: 0.85rem;
+    cursor: pointer;
+    transition: background-color 0.15s;
+}
+
+.btn-send:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+.btn-send:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread Panel */
+.thread-panel {
+    background: #2b2d31;
+    color: #dbdee1;
+    display: flex;
+    flex-direction: column;
+    border-left: 1px solid #1e1f22;
+    overflow: hidden;
+}
+
+.thread-header {
+    display: flex;
+    align-items: center;
+    justify-content: space-between;
+    padding: 12px 16px;
+    border-bottom: 1px solid #3f4147;
+    flex-shrink: 0;
+}
+
+.thread-header h3 {
+    margin: 0;
+    font-size: 1rem;
+    color: #f2f3f5;
+}
+
+.btn-close-thread {
+    background: none;
+    border: none;
+    color: #b5bac1;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+.btn-close-thread:hover {
+    background: #404249;
+    color: #f2f3f5;
+}
+
+.thread-root-message {
+    padding: 12px 16px;
+    background: #232428;
+    border-radius: 4px;
+    margin: 12px 16px 0;
+}
+
+.thread-divider {
+    border: none;
+    border-top: 1px solid #3f4147;
+    margin: 12px 16px;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0 16px;
+    display: flex;
+    flex-direction: column;
+    gap: 8px;
+}
+
+.thread-reply {
+    padding: 8px 12px;
+    border-radius: 4px;
+}
+
+.thread-reply:hover {
+    background: #35373c;
+}
